def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    bob_bid = None
    cindy_bid = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if agent_id == 'Bob':
                    bob_bid = bid
                elif agent_id == 'Cindy':
                    cindy_bid = bid

    if budget <= 0:
        return 0.0

    units = supply / float(WATER_REQ)
    scarce = units < (len(alive) + 1)
    very_scarce = units < max(1.5, (len(alive) + 1) * 0.7)

    danger = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if not alive:
        if critical:
            return float(min(budget, 40.0))
        return float(min(budget, 15.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    target = 0.0

    if critical:
        if bob_bid is not None:
            target = max(88.0, bob_bid + 3.0)
        else:
            target = 90.0
        if cindy_bid is not None and cindy_bid < target and cindy_bid <= 110:
            target = cindy_bid + 2.0
    elif danger:
        if very_scarce:
            if bob_bid is not None:
                target = max(80.0, bob_bid + 2.0)
            else:
                target = 82.0
        elif scarce:
            if bob_bid is not None:
                target = max(72.0, bob_bid + 1.5)
            else:
                target = 74.0
        else:
            target = 46.0
    else:
        if very_scarce:
            if bob_bid is not None:
                target = max(76.0, bob_bid + 1.0)
            else:
                target = 78.0
        elif scarce:
            if bob_bid is not None:
                target = max(60.0, min(76.0, bob_bid - 2.0))
            else:
                target = 62.0
        else:
            target = 28.0

    if cindy_bid is not None and cindy_bid >= 120 and not danger:
        target = min(target, 65.0 if scarce else 30.0)

    if day >= 8:
        target += 4.0
    if hp >= 8 and not scarce:
        target -= 4.0

    target = max(0.0, min(float(budget), target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace:
            prev_bids.append(trace['bid'])

    max_prev = max(prev_bids) if prev_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(max_prev + 5.0, 95.0))

    target = min(max_prev + 2.0, 90.0)
    return min(my_status['budget'], max(target, 75.0))
